        int n;
        cin >> n;
        string s;
        cin >> s;

        int ans = 1, x = 0;
        for(int i = 1; i < n; i++) {
            if(s[i] != s[i - 1]) ans++;
            if(i == n - 1) break;

            if(s[i] != s[i - 1] && s[i] != s[i + 1]) {
