#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
    int t;
    cin >> t;
    while(t--) {
        int n;
        cin >> n;
        string a, b;
        cin >> a >> b;

        ll ans = 0;
        bool ok = true;

        for(int k = 0; k < 2; k++) {
            vector<int> p1, p2;
            for(int i = k; i < n; i += 2) {
                if(a[i] == '1') p1.push_back(i);
                if(b[i] == '1') p2.push_back(i);
            }

            if(p1.size() != p2.size()) {
                ok = false;
                break;
            }

            for(int i = 0; i < p1.size(); i++) ans += abs(p1[i] - p2[i]);
        }

        if(!ok) cout << -1 << endl;
        else cout << ans / 2 << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
    int t;
    cin >> t;
    while(t--) {
        int n;
        cin >> n;
        vector<ll> b(n);
        map<ll, ll> freq;

        for(int i = 0; i < n; i++) {
            cin >> b[i];
            freq[b[i]]++;
        }

        if (!freq.count(0)) {
            cout << -1 << endl;
            continue;
        }

        map<ll, ll> ans;
        ll prv_shadow = 0, prv_cnt = 0, lst = 0;
        bool ok = true;

        for(auto [cur_shadow, cur_cnt] : freq) {
            if(cur_shadow != 0) {
                ll diff = cur_shadow - prv_shadow;

                if(diff % prv_cnt != 0) {
                    ok = false;
                    break;
                }

                ll u = diff / prv_cnt;
                if(u <= lst) {
                    ok = false;
                    break;
                }

                ans[prv_shadow] = u;
                lst = u;
            }

            prv_shadow = cur_shadow;
            prv_cnt = cur_cnt;
        }

        if(!ok) {
            cout << -1 << endl;
            continue;
        }

        ans[prv_shadow] = lst + 1;
        for(int i = 0; i < n; ++i) cout << ans[b[i]] << " \n"[i == n - 1];
    }
}

#include <bits/stdc++.h>
#define int long long
using namespace std;

void solve() {
    int n, cur = 0;
    cin >> n;
    multiset<int> b;
    for(int i = 0; i < n; i++) {
        int x;
        cin >> x;
        b.insert(x);
    }

    vector<int> ans(n);
    for(int i = 0; i < n; i++){
        auto it = b.lower_bound(1 - cur);
        if(it == b.end()) return void(cout << -1 << '\n');
        cur += *it;
        b.erase(it);
        ans[i] = cur;
    }

    for(int i = 0; i < n; i++) cout << ans[i] << " \n"[i == n - 1];
}

